import json
d=json.load(open('examples.json'))
exp=[x for x in d if x['name']=='short-stream'][0]['expected']
got=json.load(open('/workspace/tmp/out2.json'))
def diff(a,b,path=''):
    if type(a) is not type(b): print('TYPE',path,a,b); return
    if isinstance(a,dict):
        for k in a.keys()|b.keys():
            if k not in a: print('EXTRA',path+'.'+k,b[k])
            elif k not in b: print('MISSING',path+'.'+k,a[k])
            else: diff(a[k],b[k],path+'.'+k)
    elif isinstance(a,list):
        if len(a)!=len(b): print('LEN',path,len(a),len(b))
        for i,(x,y) in enumerate(zip(a,b)): diff(x,y,path+'[%d]'%i)
    else:
        if a!=b: print('VAL',path,repr(a),repr(b))
diff(exp,got)
"
